package explorer

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/oci"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewMode represents the current mode of the view
type ViewMode int

const (
	ModeNormal ViewMode = iota
	// ModeSelecting is the clone selection: the same tree, with a checkbox on
	// every row and `Space` ticking it (§3.16, decision 8).
	ModeSelecting
	// ModeCloning is the discovery-and-clone pipeline: a flat list of what has
	// been found, each row carrying its own state. It replaced the modal that
	// said "Pulling..." for however many minutes the subtree took (decision 9).
	ModeCloning
	ModeLoadingTemplates
	ModeCreatingProject
	ModeConfirmingDelete
)

// Model represents the model of the GitLab Explorer view
type Model struct {
	config *config.Config
	shared *shared.State
	width  int
	height int

	// Table
	table   datatable.Model[explorerRow]
	spinner spinner.Model

	// Tree state
	nodes         []*TreeNode
	loading       bool
	firstLoadDone bool // true after the first load attempt completes (success or error)
	error         string

	// Drill-down navigation
	currentGroupNode *TreeNode   // nil = root level
	navigationStack  []*TreeNode // Stack of parent groups for backspace navigation
	cursorStack      []int       // Cursor positions per level for restoration on drill-up

	mode ViewMode

	// Clone selection and the run it starts. The selection outlives every
	// drill-down — it names paths, not rows — and survives the round trip
	// through the workspaces view that picks the destination.
	selection cloneSelection
	// selectionNodes is where the walk starts from, one node per root. The
	// selection cannot hold them: it has to answer for paths nobody has fetched,
	// which is the whole reason it is paths and exclusions (decision 11). And a
	// root ticked three levels down is no longer on screen once the user has come
	// back up, so the reference has to be kept when it is made.
	selectionNodes map[string]*TreeNode
	clone          *cloneList

	// Creation mode state
	creationForm       *components.CreationForm
	creationParentName string              // Parent stashed during template loading
	creationParentID   string              // Parent ID stashed during template loading
	templateEntries    []oci.TemplateEntry // Loaded template entries for repo+tag resolution

	// Tab navigation
	activeTabIndex int // Focused tab index (last tab = current level)

	// Delete mode state
	deleteConfirmModal *components.OptionConfirmModal
	deleteTargetNode   *TreeNode
	// jobs is the router's last snapshot of the registry, and jobFrame the
	// spinner frame that goes with it — bare, because it lands in a table cell
	// and a cell is measured before it is styled (Rule 122).
	//
	// The frame comes from the broadcast rather than from this view's own
	// spinner because that chain stops when the tree settles: a create started
	// on a loaded tree would sit on frame zero, which reads as a hang. It is
	// the same reason the clone rows take it (D5).
	jobs     []jobs.Run
	jobFrame string

	// Transient footer messages, both cleared by the same 3s timer (Rule 128).
	// footer is the one line of transient state below the viewport (Rule 128).
	footer components.FooterMessage
}

// New creates a new instance of the explorer model
func New(cfg *config.Config, sharedState *shared.State) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		config:    cfg,
		shared:    sharedState,
		nodes:     []*TreeNode{},
		loading:   false,
		mode:      ModeNormal,
		selection: newCloneSelection(),
		table: datatable.New(datatable.Config[explorerRow]{
			Columns: explorerColumns(),
			// The forge's own order: loadChildren stacks the namespaces, then
			// the repositories. It used to be a sort by node type, which on
			// that list is the identity — so the opening screen is unchanged,
			// and what is gained is that `.` now has "no sort" as a stop, so
			// the forge's order is reachable again after cycling away from it.
			SortColumn: -1,
		}),
		spinner: s,
	}
}

// Init initializes the model
func (m Model) Init() tea.Cmd {
	// Load the root groups at startup
	if m.shared.IsAuthenticated {
		m.loading = true
		return tea.Batch(m.spinner.Tick, m.loadRootGroups())
	}
	return nil
}

// InEditMode returns true if the view is in an edit mode or filter search.
//
// `m.mode != ModeNormal` already covers both clone modes, which is what it has
// to do: `c`, `space` and `esc` all mean something there, and a bare `:` would
// otherwise open command mode over a selection in progress.
func (m Model) InEditMode() bool {
	return m.creationForm != nil || m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	if m.mode == ModeCloning && m.clone != nil {
		return m.clone.table.FilterBar().IsVisible()
	}
	return m.showsTree() && m.table.FilterBar().IsVisible()
}

// tabCount returns the total number of tabs (home + navigation stack + current group)
func (m Model) tabCount() int {
	count := 1 // home tab
	for _, node := range m.navigationStack {
		if node != nil {
			count++
		}
	}
	if m.currentGroupNode != nil {
		count++
	}
	return count
}

// resize adjusts table dimensions based on terminal size
func (m *Model) resize(width, height int) {
	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so
	// only the table's own header row is subtracted. The Rule 116 arithmetic is
	// the component's — seven ratios and a remainder used to live here.
	m.table.Resize(width, max(height-1, 1))
	if m.clone != nil {
		m.clone.table.Resize(width, max(height-1, 1))
	}
}

package components

import (
	"sync/atomic"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// FooterMessage is the one line of state every view shows below its viewport
// (Rules 124, 128). It owns both the text and the three-second timer, which is
// what makes it a component rather than a rendering helper: eight views each
// carried their own pair of fields, their own clear message and their own
// lipgloss block, and that is how the errors ended up left-aligned everywhere
// while the notices were centred — nobody ever centred the error branch.
//
// Usage, from Update() only (Rule 110):
//
//	case SomethingFailedMsg:
//	    return m, m.footer.Error("Failed to load — check logs")
//
//	default:
//	    if m.footer.Handle(msg) {
//	        return m, nil
//	    }
//
// And from View(), which stays read-only:
//
//	m.footer.View(width, components.Status{Text: m.actionLine()})

// FooterMsgDuration is how long a timed message stays on screen (Rule 128).
//
// It is an exported var rather than a const because tea.Tick really sleeps, and
// a test that inspects a Cmd carrying this timer — testutil.Msgs runs the whole
// batch — pays the full three seconds per assertion. internal/ui/testutil
// shortens it from its init, so every view test package gets that for free; the
// production value is what this file states and what
// TestAMessageGetsThreeSeconds pins.
var FooterMsgDuration = 3 * time.Second

// Level is a footer message's severity. It decides the colour and nothing else.
//
// The three are defined by what happened, not by how it feels:
//
//	LevelError   — an operation failed, or the system refused it.
//	LevelWarning — the action cannot be honoured as asked, but nothing failed:
//	               a precondition is unmet, or it is already running.
//	LevelInfo    — a neutral fact, or an operation that succeeded.
type Level int

const (
	LevelInfo Level = iota
	LevelWarning
	LevelError
)

// Style returns the style a level renders in.
func (l Level) Style() lipgloss.Style {
	switch l {
	case LevelError:
		return theme.FooterErrorStyle
	case LevelWarning:
		return theme.FooterWarnStyle
	default:
		return theme.FooterInfoStyle
	}
}

// Status is what a view derives on every frame: a progress line, a hint, or a
// table loading its rows. It carries no timer — a batch outlives the three
// seconds a message gets, which is why the sync and prune lines were rendered
// from state rather than assigned to footerInfo in the first place.
//
// It is a parameter of View rather than a field of FooterMessage because it is
// derived, not stored: containers' action line comes from BusyLabels(), which
// changes with no event to push it on.
type Status struct {
	Text string
	// Spinner prepends the current spinner frame — a table loading its rows.
	Spinner bool
	// Level colours the line, and the zero value is LevelInfo, so a status that
	// says nothing about it renders exactly as it always did.
	//
	// A derived state can be a failure as legitimately as it can be progress:
	// "Docker unreachable" is not an event that happened once, it is what is
	// true right now, and a message would expire after three seconds — which is
	// D47 in one field. It needs the colour of an error and the lifetime of a
	// state, and only Status can give it both.
	Level Level
}

// footerMsgSeq numbers messages so a timer can name the one it was started for.
var footerMsgSeq atomic.Uint64

// ClearFooterMsg expires the message identified by ID.
//
// The ID is what makes the type safe to share across packages. Two things would
// otherwise go wrong: a timer started by one view could clear the message of
// whichever view is active when it lands, and — the bug that was already
// present in all eight local implementations — a message set at t+2.9s was
// wiped at t+3s by its predecessor's timer.
type ClearFooterMsg struct{ ID uint64 }

// PostFooterMsg puts a message in whichever footer is on screen.
//
// It exists for the router, which has none of its own: RenderFooter is the
// active view's (internal/app/view.go), and the one thing the router has to say
// — that the MCP server did not start (§3.61) — belongs on screen at startup,
// not in a log. Every view already offers unhandled messages to Handle, so a
// broadcast lands wherever the user is without any view knowing what it is
// about.
//
// It carries its own ID because the timer is the sender's: PostFooter builds
// both, so the rule that a message set without its timer never clears holds
// here too (Rule 128).
//
// **It lands only where a view holds a FooterMessage.** internal/ui/forge/auth
// renders a footer but declares none, so a broadcast posted while that view is
// on screen reaches nobody — and the router switches to it whenever a context
// has no forge credentials. That is a real gap and not a silent one: the only
// broadcast today is the MCP server's, and its state is also on the `mcp` tab
// of the configuration view, which holds it for as long as it is true rather
// than for three seconds. A second use of this door would need auth to declare
// a footer first.
type PostFooterMsg struct {
	ID    uint64
	Level Level
	Text  string
}

// PostFooter builds the broadcast and the timer that expires it.
//
// For the router. A view has its own footer and calls Info, Warn or Error on
// it — going through here would be a second way to do what a field already
// does, and the message would be adopted by whatever view is active rather than
// by the one that meant it.
func PostFooter(level Level, text string) tea.Cmd {
	if text == "" {
		return nil
	}
	id := footerMsgSeq.Add(1)
	return tea.Batch(
		func() tea.Msg { return PostFooterMsg{ID: id, Level: level, Text: text} },
		tea.Tick(FooterMsgDuration, func(time.Time) tea.Msg { return ClearFooterMsg{ID: id} }),
	)
}

// FooterMessage holds the current message, its level and its identity.
type FooterMessage struct {
	text         string
	level        Level
	id           uint64
	spinnerFrame string
}

// Info, Warn and Error set the message and return its expiry timer. Call them
// from Update() and return the Cmd — a message set without its timer never
// clears (Rule 128).
func (f *FooterMessage) Info(text string) tea.Cmd  { return f.set(text, LevelInfo) }
func (f *FooterMessage) Warn(text string) tea.Cmd  { return f.set(text, LevelWarning) }
func (f *FooterMessage) Error(text string) tea.Cmd { return f.set(text, LevelError) }

